    /** The msm:consumable of {@code msm_test:ruby_tonic}, from vanilla's drink defaults (as msm_runtime). */
    private static Consumable rubyTonicConsumable() {
        Consumable.Builder builder = Consumables.defaultDrink()
                .consumeSeconds(1.0f)
                .hasConsumeParticles(true);
        applyEffects("msm_test:ruby_tonic", "msm:consumable", Identifier.fromNamespaceAndPath("minecraft", "speed"), 600, 1, 1.0f).forEach(builder::onConsume);
        applyEffects("msm_test:ruby_tonic", "msm:consumable", Identifier.fromNamespaceAndPath("minecraft", "regeneration"), 100, 0, 1.0f).forEach(builder::onConsume);
        return builder.build();
    }

    /** The msm:consumable of {@code msm_test:ruby_pie}, from vanilla's food defaults (as msm_runtime). */
